import java.util.Scanner;

public class Main {
    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] 条数们 = new int[n];
        for (int i = 0; i < n; i++) {
            条数们[i] = sc.nextInt();
        }

        int[] 收货格子 = new int[n];
        Thread[] 一队 = new Thread[n];
        for (int i = 0; i < n; i++) {
            一队[i] = new Thread(new FishJob(i + 1, 条数们[i], 收货格子));
        }
        for (int i = 0; i < n; i++) {
            一队[i].start();
        }
        for (int i = 0; i < n; i++) {
            一队[i].join();
        }

        int 一共 = 0;
        for (int i = 0; i < n; i++) {
            System.out.println("第 " + (i + 1) + " 只：" + 收货格子[i] + " 条");
            一共 = 一共 + 收货格子[i];
        }
        System.out.println("一共：" + 一共 + " 条");
    }
}

class FishJob implements Runnable {
    int 第几只;
    int 要捞;
    int[] 收货格子;

    FishJob(int 第几只, int 要捞, int[] 收货格子) {
        this.第几只 = 第几只;
        this.要捞 = 要捞;
        this.收货格子 = 收货格子;
    }

    public void run() {
        int 数到 = 0;
        for (int i = 0; i < 要捞; i++) {
            数到 = 数到 + 1;
        }
        收货格子[第几只 - 1] = 数到;
    }
}
